// Import of required libraries
import { test, expect, SkyrampClient } from '@skyramp/skyramp';
import {
    MEMBER_PASSWORD,
    MEMBER_USERNAME,
    createCollection,
    getCollectionMembers,
    resolveUserId,
    signInAs,
    transferCollection,
    updateCollection,
} from './skyrampUtils';

test('testIntegration', async ({ playwright }) => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const { userId: memberUserId, usersPostResponse } = await resolveUserId(client);
    // The account this test transfers the collection to is registered on the first run and
    // already present on every later one; both outcomes are asserted for what they are.
    if (usersPostResponse.statusCode === 400) {
        expect(JSON.parse(usersPostResponse.responseBody).response, 'the secondary account is already registered')
            .toBe("Email or Username already exists.");
    } else {
        expect(usersPostResponse.statusCode, 'status code').toBe(201);
    }
    expect(Number.isInteger(memberUserId), 'the secondary account this test transfers to has a numeric id').toBe(true);
    const collectionName = `transfer-lifecycle-${Date.now()}`;

    const collectionsPostResponse = await createCollection(client, collectionName);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    const createdCollection = JSON.parse(collectionsPostResponse.responseBody).response;
    const collectionId = Number(createdCollection.id);
    const originalOwnerId = Number(createdCollection.ownerId);
    expect(Number.isInteger(collectionId), 'the created collection carries a numeric id').toBe(true);
    expect(createdCollection.name, 'the created collection name').toBe(collectionName);
    expect(createdCollection.members, 'a freshly created collection has no members').toEqual([]);
    expect(createdCollection.members[0], 'a freshly created collection has no first member').toBeUndefined();
    expect(createdCollection.color, 'color echoes the value the request sent').toBe("#0ea5e9");
    expect(createdCollection.description, 'description echoes the value the request sent').toBe("");
    expect(createdCollection.isPublic, 'isPublic echoes the value the request sent').toBe(false);
    expect(collectionId, 'the collection id the server assigned').toBeGreaterThan(0);
    expect(createdCollection.createdAt, 'createdAt is an ISO timestamp').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const collectionsCollectionsPutResponse = await updateCollection(client, collectionId, collectionName, [
        { canCreate: true, canDelete: false, canUpdate: true, userId: memberUserId },
    ]);
    expect(collectionsCollectionsPutResponse.statusCode, 'status code').toBe(200);

    const membersGetResponse = await getCollectionMembers(client, collectionId);
    expect(membersGetResponse.statusCode, 'status code').toBe(200);
    const membersBeforeTransfer = JSON.parse(membersGetResponse.responseBody).response;
    expect(membersBeforeTransfer, 'the collection has exactly the invited account as a member').toHaveLength(1);
    expect(Number(membersBeforeTransfer[0].userId), 'member userId').toBe(memberUserId);
    expect(Number(membersBeforeTransfer[0].collectionId), 'member collectionId').toBe(collectionId);
    expect(Number(membersBeforeTransfer[0].user.id), 'the member row carries the user record').toBe(memberUserId);
    expect(membersBeforeTransfer[0].canUpdate, 'the member kept the write permission it was added with').toBe(true);
    expect(membersBeforeTransfer[0].canCreate, 'canCreate echoes the value the request sent').toBe(true);
    expect(membersBeforeTransfer[0].canDelete, 'canDelete echoes the value the request sent').toBe(false);
    expect(membersBeforeTransfer[0].createdAt, 'the member row carries an ISO timestamp').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(membersBeforeTransfer[1], 'the collection has no second member').toBeUndefined();

    const transferPostResponse = await transferCollection(client, collectionId, { toUserId: memberUserId });
    expect(transferPostResponse.statusCode, 'status code').toBe(200);
    const transferred = JSON.parse(transferPostResponse.responseBody).response;
    expect(Number(transferred.id), 'the transfer response names the collection').toBe(collectionId);
    expect(transferred.name, 'the transfer leaves the collection name alone').toBe(collectionName);
    expect(Number(transferred.ownerId), 'ownership moved to the member').toBe(memberUserId);
    expect(Number(transferred.ownerId), 'ownership no longer sits with the previous owner').not.toBe(originalOwnerId);

    const membersGet1Response = await getCollectionMembers(client, collectionId, 403);
    expect(membersGet1Response.statusCode, 'status code').toBe(403);
    expect(JSON.parse(membersGet1Response.responseBody).response,
        'the previous owner is told why the collection is refused')
        .toBe("Only the owner can manage members.");

    // The rest of the collection's life belongs to its new owner, so read and clean up as them.
    const newOwner = await signInAs(playwright, MEMBER_USERNAME, MEMBER_PASSWORD);
    let memberListStatus = 0;
    let memberUserIdsAfterTransfer: number[] = [];
    let collectionsCollectionsDeleteResponse = { statusCode: 0 };
    try {
        const membersAsNewOwner = await newOwner.get(`/api/v1/collections/${collectionId}/members`);
        memberListStatus = membersAsNewOwner.status();
        if (memberListStatus === 200) {
            memberUserIdsAfterTransfer = ((await membersAsNewOwner.json()).response ?? [])
                .map((member: any) => Number(member.userId));
        }
        // Deleted before anything below is asserted, so the collection this test created is
        // removed whether the assertions that follow pass or fail.
        collectionsCollectionsDeleteResponse = {
            statusCode: (await newOwner.delete(`/api/v1/collections/${collectionId}`)).status(),
        };
    } finally {
        await newOwner.dispose();
    }

    expect(memberListStatus, 'the new owner can manage the members of the collection they now own').toBe(200);
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    // A collection's owner is never also one of its members: updateCollectionById filters the
    // owner out of the members it writes, so the transfer has to drop the row that made the
    // new owner eligible for it.
    expect(memberUserIdsAfterTransfer, 'the members of the collection after the ownership transfer')
        .not.toContain(memberUserId);
});
